# Generated by build.py from recipe.yml for recipe ftp-move-a-client-to-sftp. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'ssh-keygen -q -t rsa -b 3072 -N "" -f host_key'
cmd /c 'head -c 3000 /dev/urandom > site/report.bin'
$server0 = Start-Process surl -ArgumentList '--hostkey', 'host_key', '--user', 'alice:s3cret', '--allow-plaintext-auth', '--list-directories', '--directory', 'site', '-v', '--log-file', 'surl.log', 'ftp://127.0.0.1:8080/', 'sftp://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
curl.exe -sS -k -u alice:s3cret -T site/report.bin sftp://127.0.0.1:8083/report.bin
try { curl.exe -sS -u alice:s3cret -o over-ftp.bin ftp://127.0.0.1:8080/report.bin --next -sS -k -u alice:s3cret -o over-sftp.bin sftp://127.0.0.1:8081/report.bin && cmp over-ftp.bin over-sftp.bin && echo identical } finally { Stop-Process $server0 }
